class Solution:
    def maxAlternatingScore(self, nums: List[int], k: int) -> int:
        n = len(nums)
        up = [0] * n
        dn = [0] * n
        ans = 0
        for i in range(n):
            up[i] = dn[i] = nums[i]
            for j in range(0, i - k + 1):
                if nums[j] < nums[i]:
                    up[i] = max(up[i], nums[i] + dn[j])
                if nums[j] > nums[i]:
                    dn[i] = max(dn[i], nums[i] + up[j])
            ans = max(ans, up[i], dn[i])
        return ans

