class Solution {
public:
    long long maxAlternatingScore(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> vals = nums;
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        int m = vals.size(), size = 1;
        while (size < m) size <<= 1;
        const long long NEG = LLONG_MIN / 2;
        vector<long long> t0(2 * size, NEG), t1(2 * size, NEG);
        auto upd = [&](vector<long long>& t, int i, long long v) {
            i += size;
            if (t[i] >= v) return;
            t[i] = v;
            for (i >>= 1; i; i >>= 1) t[i] = max(t[2 * i], t[2 * i + 1]);
        };
        auto qry = [&](vector<long long>& t, int l, int r) {
            long long res = NEG;
            l += size; r += size + 1;
            while (l < r) {
                if (l & 1) res = max(res, t[l++]);
                if (r & 1) res = max(res, t[--r]);
                l >>= 1; r >>= 1;
            }
            return res;
        };
        vector<long long> dp(n);
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            int j = i - k;
            if (j >= 0) {
                int p = lower_bound(vals.begin(), vals.end(), nums[j]) - vals.begin();
                upd(t0, p, dp[j]);
                upd(t1, p, dp[j]);
            }
            int p = lower_bound(vals.begin(), vals.end(), nums[i]) - vals.begin();
            long long best = NEG;
            if (p > 0) best = max(best, qry(t0, 0, p - 1));
            if (p < m - 1) best = max(best, qry(t1, p + 1, m - 1));
            dp[i] = nums[i] + max(0LL, best);
            ans = max(ans, dp[i]);
        }
        return ans;
    }
};

