class Solution {
    public long maxAlternatingScore(int[] nums, int k) {
        int n = nums.length;
        int[] vals = nums.clone();
        Arrays.sort(vals);
        int m = 0;
        for (int x : vals) if (m == 0 || vals[m - 1] != x) vals[m++] = x;
        int size = 1;
        while (size < m) size <<= 1;
        long NEG = Long.MIN_VALUE / 2;
        long[] t0 = new long[2 * size], t1 = new long[2 * size];
        Arrays.fill(t0, NEG);
        Arrays.fill(t1, NEG);
        long[] dp = new long[n];
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int j = i - k;
            if (j >= 0) {
                int p = Arrays.binarySearch(vals, 0, m, nums[j]);
                if (p < 0) p = -p - 1;
                upd(t0, size, p, dp[j]);
                upd(t1, size, p, dp[j]);
            }
            int p = Arrays.binarySearch(vals, 0, m, nums[i]);
            if (p < 0) p = -p - 1;
            long best = NEG;
            if (p > 0) best = Math.max(best, qry(t0, size, 0, p - 1));
            if (p < m - 1) best = Math.max(best, qry(t1, size, p + 1, m - 1));
            dp[i] = nums[i] + Math.max(0, best);
            ans = Math.max(ans, dp[i]);
        }
        return ans;
    }
    void upd(long[] t, int size, int i, long v) {
        i += size;
        if (t[i] >= v) return;
        t[i] = v;
        for (i >>= 1; i > 0; i >>= 1) t[i] = Math.max(t[2 * i], t[2 * i + 1]);
    }
    long qry(long[] t, int size, int l, int r) {
        long res = Long.MIN_VALUE / 2;
        l += size; r += size + 1;
        while (l < r) {
            if ((l & 1) == 1) res = Math.max(res, t[l++]);
            if ((r & 1) == 1) res = Math.max(res, t[--r]);
            l >>= 1; r >>= 1;
        }
        return res;
    }
}

