var maxAlternatingScore = function(nums, k) {
    const n = nums.length;
    const vals = [...new Set(nums)].sort((a, b) => a - b);
    const m = vals.length;
    let size = 1;
    while (size < m) size *= 2;
    const NEG = -Infinity;
    const mk = () => new Array(2 * size).fill(NEG);
    const t0 = mk(), t1 = mk();
    const upd = (t, i, v) => {
        i += size;
        if (t[i] >= v) return;
        t[i] = v;
        for (i >>= 1; i > 0; i >>= 1) t[i] = Math.max(t[2 * i], t[2 * i + 1]);
    };
    const qry = (t, l, r) => {
        let res = NEG;
        l += size; r += size + 1;
        while (l < r) {
            if (l & 1) res = Math.max(res, t[l++]);
            if (r & 1) res = Math.max(res, t[--r]);
            l >>= 1; r >>= 1;
        }
        return res;
    };
    const dp = new Array(n);
    let ans = 0;
    for (let i = 0; i < n; i++) {
        const j = i - k;
        if (j >= 0) {
            const p = vals.indexOf(nums[j]);
            upd(t0, p, dp[j]);
            upd(t1, p, dp[j]);
        }
        const p = vals.indexOf(nums[i]);
        let best = NEG;
        if (p > 0) best = Math.max(best, qry(t0, 0, p - 1));
        if (p < m - 1) best = Math.max(best, qry(t1, p + 1, m - 1));
        dp[i] = nums[i] + Math.max(0, best);
        ans = Math.max(ans, dp[i]);
    }
    return ans;
};
